fn solve(a: i8, b: i8, c: i8) -> i8 {
    let mut v = [a as i32, b as i32, c as i32];
    v.sort();
    let (x, y, z) = (v[0], v[1], v[2]);

    // Total sum increases by 2 each operation, so final sum parity is fixed.
    // We can reach any target T >= z with matching parity to current sum.
    let sum = x + y + z;

    let mut best = i32::MAX;
    for t in z..=200 {
        let s_final = 3 * t;
        if (s_final - sum) % 2 != 0 {
            continue;
        }
        let dx = t - x;
        let dy = t - y;
        let dz = t - z;
        if dx < 0 || dy < 0 || dz < 0 {
            continue;
        }

        // Each operation can add at most 2 to total deficit, so lower bound is total/2.
        // Also, in one op we can increase any single number by 2, so we can spend
        // dz/2 ops solely on the current maximum if needed -> bound by max deficit.
        let total_def = dx + dy + dz; // even
        let ops = (total_def / 2).max(dx.max(dy).max(dz));
        best = best.min(ops);
    }

    best as i8
}